export async function maybeAutoDeploySprintBatchPr(opts: {
  jobId: string
  userId: string
  productId: string
  sprintRunId: string
}): Promise<void> {
  // (1) Level check
  const run = await prisma.sprintRun.findUnique({
    where: { id: opts.sprintRunId },
    select: { id: true, status: true },
  })
  if (run?.status !== 'DONE') return

  // (2) Resolve the product-repo batch-PR
  const product = await prisma.product.findUnique({
    where: { id: opts.productId },
    select: { repo_url: true },
  })
  const prJobs = await prisma.claudeJob.findMany({
    where: { sprint_run_id: opts.sprintRunId, pr_url: { not: null } },
    orderBy: { created_at: 'asc' },
    select: { pr_url: true, head_sha: true, task: { select: { repo_url: true } } },
  })
  const productPrJob = prJobs.find(
    (j) => repoBucketKey(j.task?.repo_url, product?.repo_url) === null,
  )
  if (!productPrJob?.pr_url) {
    console.warn(`[sprint-batch-deploy] geen product-repo batch-PR gevonden voor sprint-run ${opts.sprintRunId}; auto-deploy skip`)
    return
  }
  const prUrl = productPrJob.pr_url

  // (3) head-sha, self-resolving (never cross-repo sha)
  let headSha = productPrJob.head_sha
  if (!headSha) {
    const info = await getPullRequestState({ prUrl })
    if ('error' in info) {
      console.warn(`[sprint-batch-deploy] head-sha onberek...`)
      return
    }
    headSha = info.headSha
    if (!headSha) { warn; return }
  }

  // (4a) preflight
  const eligibility = await checkDeployEligibility(opts.productId)
  if (eligibility === 'not_configured') return // silent — no auto-deploy configured
  if (eligibility === 'blocked') {
    void triggerPush(...)
    return
  }

  // (4c) Enable auto-merge
  const outcomes = await executeEffects([{ type: 'ENABLE_AUTO_MERGE', prUrl, expectedHeadSha: headSha }])
  const eo = outcomes.find((o) => o.effect === 'ENABLE_AUTO_MERGE')
  if (!eo || !eo.ok) {
    console.warn(...)
    void triggerPush(...)
    return
  }

  // (4d) Enqueue with observability of the second check
  const outcome = await maybeEnqueueDeployJob({ parentJobId: opts.jobId, userId: opts.userId, productId: opts.productId, prUrl, headSha }).catch((err: unknown) => {
    console.error('[sprint-batch-deploy] deploy-enqueue error:', err)
    void triggerPush(opts.userId, {...})
    return 'error' as const
  })
  // Second check: race between preflight and enqueue (config toggle / new FAILED DEPLOY)
  if (outcome === 'not_configured' || outcome === 'blocked' || outcome === 'error') {
    void triggerPush(opts.userId, { title: ..., body: `deploy-enqueue ${outcome}`, url: '/jobs', tag: `deploy-enqueue-${opts.jobId}` })
  }
}
