export async function maybeAutoDeploySprintBatchPr(opts: {
  jobId: string
  userId: string
  productId: string
  sprintRunId: string
}): Promise<void> {
  const { jobId, userId, productId, sprintRunId } = opts

  // (1) Level check: only when sprint run is DONE.
  const run = await prisma.sprintRun.findUnique({
    where: { id: sprintRunId },
    select: { status: true },
  })
  if (run?.status !== 'DONE') return

  const product = await prisma.product.findUnique({
    where: { id: productId },
    select: { repo_url: true },
  })

  // (2) Resolve the batch PR of the product-repo via repoBucketKey —
  // never a cross-repo sha.
  const prJobs = await prisma.claudeJob.findMany({
    where: { sprint_run_id: sprintRunId, pr_url: { not: null } },
    orderBy: { created_at: 'asc' },
    select: { pr_url: true, head_sha: true, task: { select: { repo_url: true } } },
  })
  const productPrJob = prJobs.find(
    (j) => repoBucketKey(j.task?.repo_url, product?.repo_url) === null,
  )
  if (!productPrJob?.pr_url) {
    console.warn(`[sprint-batch-deploy] no product-repo batch PR for sprint run ${sprintRunId} (job ${jobId}); skipping auto-deploy`)
    return
  }
  const prUrl = productPrJob.pr_url

  // (3) headSha self-resolving: the saved value wins, otherwise
  // resolve from Forgejo — never a cross-repo sha.
  let headSha: string | null = productPrJob.head_sha
  if (headSha == null) {
    const state = await getPullRequestState({ prUrl })
    if (state.error) {
      console.warn(`[sprint-batch-deploy] no head sha for ${prUrl} (job ${jobId}); skipping auto-deploy: ${state.error}`)
      return
    }
    headSha = state.headSha
  }
  if (headSha == null) {
    console.warn(...skip)
    return
  }

  // (4a) Preflight.
  const eligibility = await checkDeployEligibility(productId)
  if (eligibility === 'not_configured') return // silently
  if (eligibility === 'blocked') {
    void triggerPush(userId, { title: ..., body: ..., url: '/jobs', tag: `sprint-batch-deploy-${jobId}` })
    return
  }

  // (4c) Enable auto-merge.
  const outcomes = await executeEffects([
    { type: 'ENABLE_AUTO_MERGE', prUrl, expectedHeadSha: headSha },
  ])
  const outcome = outcomes.find((o) => o.effect === 'ENABLE_AUTO_MERGE')
  if (!outcome || !outcome.ok) {
    void triggerPush(...)
    return // no enqueue
  }

  // (4d) Enqueue with second-check observability.
  let enqueueOutcome: string
  try {
    enqueueOutcome = await maybeEnqueueDeployJob({ parentJobId: jobId, userId, productId, prUrl, headSha })
  } catch (err) {
    console.error('[sprint-batch-deploy] deploy enqueue failed:', err)
    void triggerPush(...)
    return
  }
  if (enqueueOutcome === 'not_configured' || enqueueOutcome === 'blocked') {
    void triggerPush(...)
  }
}
```

